#!/usr/bin/env node
/**
 * Test driver: run one unsatisfiable environment twice over the same two-rung
 * attempt ladder — once on the session's own model route and once delegated to
 * one fresh in-process child per attempt — and print each report beside the
 * models its cell asked its provider for and the user messages each attempt
 * carried, for the e2e's assertions.
 *
 * Both cells run the same environment, whose check never passes, so each spends
 * exactly the ladder's two attempts and the report states the route of each.
 */

import { mkdtemp } from 'node:fs/promises'
import { join } from 'node:path'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type { EnvironmentRunReport, EnvironmentRunRung } from '@deepseek-ai/dsh-environment-runner'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { SessionId } from '@deepseek-ai/dsh-session'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('attempt-ladder driver requires a config path')

const SMALL = { provider: 'cli-mock', model: 'cli-mock-small' }
const LARGE = { provider: 'cli-mock', model: 'cli-mock-large' }
const LADDER: readonly EnvironmentRunRung[] = [{}, { model: LARGE }]

/** One cell as the driver reports it: the run, the routes it asked for, and the texts each attempt carried. */
interface Cell {
  readonly report: EnvironmentRunReport
  /** Model of every `request/header` the cell session recorded, in log order. */
  readonly requestedModels: string[]
  /** Text of every user message the implementer received, in log order. */
  readonly prompts: string[]
  /** Attempt number and restated-task flag of every delegation the cell recorded. */
  readonly delegations: { attempt: number; restatedTask: boolean }[]
}

const ctx = await boot('attempt-ladder-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the runner creates agents only over the settled application.
  await ctx.get('loader')?.await()
  const runner = ctx.get('environmentRuns')
  const persistence = ctx.get('sessionPersistence')
  if (runner === undefined || persistence === undefined) {
    throw new Error('attempt-ladder driver requires the runner and session persistence')
  }

  // A delegated child is a session of its own; the cell's own log is the one
  // that states what the cell asked for, so each cell is read back by its id.
  const read = async (report: EnvironmentRunReport): Promise<Cell> => {
    const { events } = await persistence.inspect(report.sessionId as SessionId)
    return {
      report,
      requestedModels: events.flatMap(event => (event.type === 'request/header' ? [event.data.header.config.model] : [])),
      prompts: events.flatMap(event => (
        event.type === 'user/message'
          ? event.data.message.content.flatMap(block => (block.type === 'text' ? [block.text] : []))
          : []
      )),
      delegations: events.flatMap(event => (
        event.type === 'environment/delegation'
          ? [{ attempt: event.data.attempt, restatedTask: event.data.restatedTask }]
          : []
      )),
    }
  }

  const cell = async (implementer?: { kind: 'subagent'; provider: string }): Promise<Cell> => {
    const workspace = await mkdtemp(join(process.cwd(), 'workspace-'))
    return read(await runner.run({
      environment: EnvironmentId('smoke:unsatisfiable'),
      workspace,
      model: SMALL,
      ladder: LADDER,
      ...implementer === undefined ? {} : { implementer },
    }))
  }

  const route = await cell()
  const delegated = await cell({ kind: 'subagent', provider: 'spawn' })
  process.stdout.write(`${JSON.stringify({ type: 'result', route, delegated })}\n`)
} finally {
  await ctx.fiber.dispose()
}

import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import type { EnvironmentRunReport } from '@deepseek-ai/dsh-environment-runner'
import { LOADER_SMOKE_TEST_TIMEOUT_MS, runLoaderSmoke } from '@deepseek-ai/dsh-loader-smoke'

const binScript = fileURLToPath(new URL('../../../../examples/headless-agent/tests/fixtures/attempt-ladder/driver.ts', import.meta.url))
const configPath = fileURLToPath(new URL('../../../../examples/headless-agent/tests/fixtures/attempt-ladder/cordis.yml', import.meta.url))
const repoTsconfig = fileURLToPath(new URL('../../../../tsconfig.json', import.meta.url))

/** One laddered cell as the driver reports it. */
interface Cell {
  report: EnvironmentRunReport
  requestedModels: string[]
  prompts: string[]
  delegations: { attempt: number; restatedTask: boolean }[]
}

interface DriverResult {
  type: string
  route: Cell
  delegated: Cell
}

const TASK = 'Prove the CLI tool round trip.'
const DIRECTIVE = "<validation_failed>\n1 of the standard's checks failed\n1. exit 1\nContinue working on the task; the validator runs again when you stop.\n</validation_failed>"

describe('an attempt ladder through a real cordis.yml and headless process', () => {
  it('runs each attempt on its own rung and restates the task for a fresh child', async () => {
    const { stdout, stderr } = await runLoaderSmoke({
      label: 'attempt-ladder',
      tempDirPrefix: 'attempt-ladder-e2e-',
      binScript,
      libBinScript: binScript,
      configPath,
      binArgs: [configPath],
      tsconfigPath: repoTsconfig,
    })
    expect(stderr).toBe('')
    const result = JSON.parse(stdout.trimEnd().split('\n').at(-1) ?? '') as DriverResult
    expect(result.type).toBe('result')

    // The ladder is the attempt bound: the composition allows one attempt and
    // both cells ran two, each on its own rung.
    for (const cell of [result.route, result.delegated]) {
      expect(cell.report.certified).toBe(false)
      expect(cell.report.attempts.map(attempt => attempt.model.model)).toEqual(['cli-mock-small', 'cli-mock-large'])
      expect(cell.report.attempts[0]?.model).not.toEqual(cell.report.attempts[1]?.model)
      expect(cell.report.stamp.model).toEqual({ provider: 'cli-mock', model: 'cli-mock-small' })
      expect(cell.report.stamp.ladder).toEqual([
        { provider: 'cli-mock', model: 'cli-mock-small' },
        { provider: 'cli-mock', model: 'cli-mock-large' },
      ])
    }

    // A route cell keeps its transcript: every request of the second attempt
    // went to the second rung, and the follow-up carries the directive alone.
    expect(result.route.report.attempts.map(attempt => attempt.transcript)).toEqual(['kept', 'kept'])
    expect(new Set(result.route.requestedModels)).toEqual(new Set(['cli-mock-small', 'cli-mock-large']))
    expect(result.route.requestedModels[0]).toBe('cli-mock-small')
    expect(result.route.requestedModels.at(-1)).toBe('cli-mock-large')
    expect(result.route.prompts).toEqual([TASK, DIRECTIVE])
    expect(result.route.delegations).toEqual([])

    // A delegated cell drops it: the cell drives no request of its own, and the
    // second child's prompt restates the task ahead of the same directive.
    expect(result.delegated.report.attempts.map(attempt => attempt.transcript)).toEqual(['dropped', 'dropped'])
    expect(result.delegated.requestedModels).toEqual([])
    expect(result.delegated.prompts).toEqual([])
    expect(result.delegated.delegations).toEqual([
      { attempt: 1, restatedTask: false },
      { attempt: 2, restatedTask: true },
    ])
  }, LOADER_SMOKE_TEST_TIMEOUT_MS)
})

